python - <<'PY'
import pandas as pd,numpy as np
from scipy.spatial.distance import cdist
tr=pd.read_csv('b3_te_zt_extrapolation_train.csv');po=pd.read_csv('b3_te_zt_extrapolation_pool.csv');cs=tr.columns[:-2]
print('EXACT REPEATS');
for key,g in tr.groupby(list(cs)):
 if len(g)>1: print(g[['T','target']].to_string(index=True),'composition',[(c,round(v,5)) for c,v in zip(cs,key) if v])
D=cdist(po[cs],tr[cs]);
for i,r in po.iterrows():
 idx=np.argsort(D[i])[:5]
 print(r.candidate_id,' | '.join(f'row{j}:d={D[i,j]:.4f},T={tr.iloc[j].T.iloc[-2]:.0f},y={tr.iloc[j].target:.4g}' for j in idx))
